    SET IDENTITY_INSERT [contract_templates] ON;
    INSERT INTO [contract_templates] ([template_id], [template_name], [terms_content], [is_default]) VALUES
    (1, N'Hợp đồng thuê phòng trọ tiêu chuẩn', N'1. Bên A cho Bên B thuê phòng đúng mã phòng ghi trong hợp đồng, thời hạn theo hợp đồng.
    2. Bên B đặt cọc một tháng tiền phòng, hoàn lại khi trả phòng sau khi trừ công nợ và hư hỏng.
    3. Tiền phòng trả hằng tháng trước hạn ghi trong hợp đồng; trễ hạn phạt theo ngày.
    4. Điện nước tính theo công tơ riêng, dịch vụ chung theo bảng giá của khu trọ.
    5. Không nuôi thú cưng, không gây ồn sau 22 giờ, không sửa chữa phòng khi chưa báo chủ trọ.
    6. Báo trước 30 ngày khi muốn trả phòng.', 1),
    (2, N'Hợp đồng thuê dài hạn 24 tháng', N'1. Bên A cho Bên B thuê phòng đúng mã phòng ghi trong hợp đồng, thời hạn theo hợp đồng.
    2. Bên B đặt cọc một tháng tiền phòng, hoàn lại khi trả phòng sau khi trừ công nợ và hư hỏng.
    3. Tiền phòng trả hằng tháng trước hạn ghi trong hợp đồng; trễ hạn phạt theo ngày.
    4. Điện nước tính theo công tơ riêng, dịch vụ chung theo bảng giá của khu trọ.
    5. Không nuôi thú cưng, không gây ồn sau 22 giờ, không sửa chữa phòng khi chưa báo chủ trọ.
    6. Báo trước 30 ngày khi muốn trả phòng.
    7. Hợp đồng 24 tháng: giá thuê giữ nguyên 12 tháng đầu, điều chỉnh tối đa 5% từ tháng 13 và báo trước 60 ngày.', 0),
    (3, N'Hợp đồng phòng ở ghép', N'1. Bên A cho Bên B thuê phòng đúng mã phòng ghi trong hợp đồng, thời hạn theo hợp đồng.
    2. Bên B đặt cọc một tháng tiền phòng, hoàn lại khi trả phòng sau khi trừ công nợ và hư hỏng.
    3. Tiền phòng trả hằng tháng trước hạn ghi trong hợp đồng; trễ hạn phạt theo ngày.
    4. Điện nước tính theo công tơ riêng, dịch vụ chung theo bảng giá của khu trọ.
    5. Không nuôi thú cưng, không gây ồn sau 22 giờ, không sửa chữa phòng khi chưa báo chủ trọ.
    6. Báo trước 30 ngày khi muốn trả phòng.
    7. Phòng ở ghép: Bên B đứng tên chịu trách nhiệm khai báo đầy đủ người ở cùng và đăng ký tạm trú trong 30 ngày.', 0);
    SET IDENTITY_INSERT [contract_templates] OFF;
