    (1, N'INVOICE_ISSUED', N'EMAIL', N'Hóa đơn {{invoice}} đã phát hành', N'Chào bạn, hóa đơn {{invoice}} có tổng {{amount}} đ, hạn thanh toán {{dueDate}}. Bạn có thể thanh toán bằng tiền mặt hoặc quét mã QR. Cảm ơn bạn.', 1),
    (2, N'INVOICE_ADJUSTED', N'SYSTEM_APP', N'Hóa đơn của bạn đã được điều chỉnh', N'Hóa đơn {{invoice}} vừa được điều chỉnh. Ghi chú: {{note}}. Vui lòng kiểm tra lại số tiền cần thanh toán.', 1),
    (3, N'DEBT_REMINDER_1', N'SYSTEM_APP', N'Nhắc thanh toán phòng {{room}}', N'Phòng {{room}} còn khoản chưa thanh toán {{amount}}, đã quá hạn {{overdueDays}} ngày. Bạn vui lòng thanh toán sớm nhé.', 1),
    (4, N'DEBT_REMINDER_2', N'SYSTEM_APP', N'Nhắc thanh toán lần 2, phòng {{room}}', N'Khoản nợ {{amount}} của phòng {{room}} đã quá hạn {{overdueDays}} ngày. Mong bạn thanh toán trong tuần này để tránh phát sinh phí chậm trả.', 1),
    (5, N'DEBT_FINAL_WARNING', N'SYSTEM_APP', N'Cảnh báo cuối cùng, phòng {{room}}', N'Phòng {{room}} nợ {{amount}}, quá hạn {{overdueDays}} ngày. Nếu không thanh toán, chủ trọ có thể xem xét chấm dứt hợp đồng theo điều khoản đã ký.', 1),
    (6, N'CONTRACT_EXPIRING', N'SYSTEM_APP', N'Hợp đồng {{contract}} sắp hết hạn', N'Hợp đồng {{contract}} phòng {{room}} sẽ hết hạn ngày {{endDate}}. Nếu muốn gia hạn, bạn vui lòng liên hệ chủ trọ.', 1),
    (7, N'CONTRACT_EXPIRED', N'SYSTEM_APP', N'Hợp đồng {{contract}} đã hết hạn', N'Hợp đồng {{contract}} phòng {{room}} đã hết hạn ngày {{endDate}}. Vui lòng liên hệ chủ trọ để gia hạn hoặc làm thủ tục trả phòng.', 1);
